    "mf-auto-777": "\n          /* 1. 펄스 애니메이션 정의 */\n          @keyframes pulse-border {\n            0% {\n              box-shadow: 0 0 0 0 rgba(255, 204, 0, 0.7);\n            }\n\n            70% {\n              box-shadow: 0 0 0 15px rgba(255, 204, 0, 0);\n            }\n\n            100% {\n              box-shadow: 0 0 0 0 rgba(255, 204, 0, 0);\n            }\n          }\n\n          /* 그룹화된 핫스팟 동시 활성화 로직 */\n          .mf-stage:has(> .group-tool-time:hover) .group-tool-time {\n            opacity: 1 !important;\n            pointer-events: auto !important;\n            border-color: rgba(255, 204, 0, 0.95) !important;\n            background: rgba(255, 204, 0, 0.10) !important;\n            box-shadow: 0 0 0 2px rgba(255, 204, 0, 0.18) !important;\n            animation: none !important;\n          }\n          \n          .mf-stage:has(> .group-tool-time:hover) .group-tool-time-callout {\n            opacity: 1 !important;\n            transform: translateY(0) !important;\n            pointer-events: auto !important;\n          }\n\n          /* 화살표 숨기기 전용 클래스 */\n          .mf-callout-custom.no-arrow::before,\n          .mf-callout-custom.no-arrow::after {\n            display: none !important;\n          }\n\n          /* 2. 핫스팟 컨테이너 및 기본 스타일 */\n          .mf-stage {\n            position: relative;\n            width: 100%;\n            aspect-ratio: 1586 / 930;\n            background: #000;\n            overflow: visible;\n            border-radius: var(--radius);\n          }\n\n          .mf-hotspot {\n            position: absolute;\n            border: 5px solid #ffcc00;\n            background: transparent;\n            cursor: pointer;\n            z-index: 5;\n            transition: .15s ease;\n            outline: none;\n            animation: pulse-border 2s infinite;\n          }\n\n          /* 3. 핵심 로직: 컨테이너 내부의 어떤 핫스팟이라도 hover 상태가 되면 모든 핫스팟의 애니메이션 정지 */\n          .mf-stage:has(>.mf-hotspot:hover) .mf-hotspot {\n            animation-play-state: paused;\n          }\n\n          /* 4. 마우스 오버 시 개별 핫스팟 강조 */\n          .mf-hotspot:hover {\n            border-color: rgba(255, 204, 0, 0.95);\n            background: rgba(255, 204, 0, 0.10);\n            box-shadow: 0 0 0 2px rgba(255, 204, 0, 0.18);\n          }\n\n          /* 5. 툴팁 설명창(Callout) 스타일 */\n          .mf-callout {\n            position: absolute;\n            min-width: 170px;\n            padding: 12px 16px;\n            background: rgba(144, 106, 0, 0.88);\n            color: #fff8dc;\n            border: 3px solid #ffcc00;\n            border-radius: 8px;\n            box-shadow: 0 10px 28px rgba(0, 0, 0, 0.32);\n            opacity: 0;\n            transform: translateY(6px);\n            transition: .15s ease;\n            pointer-events: none;\n            z-index: 10;\n            text-align: center;\n          }\n\n          .mf-callout .title {\n            display: block;\n            font-size: 22px;\n            line-height: 1.15;\n            font-weight: 800;\n            color: #fff;\n            margin-bottom: 4px;\n          }\n\n          .mf-callout .desc {\n            display: block;\n            font-size: 21px;\n            line-height: 1.35;\n            color: #fff4cf;\n          }\n\n          /* 마우스 오버 시 설명창 표시 */\n          .mf-hotspot:hover+.mf-callout {\n            opacity: 1;\n            transform: translateY(0);\n          }\n        ",
